"""Course relationships: generated by a captured model boundary, persisted in SQLite."""

import copy
import io
import json

import pytest
from fastapi.testclient import TestClient
from reportlab.pdfgen.canvas import Canvas

from backend.app import create_app
from backend.schemas import MapDraft


class RelationModel:
    def __init__(self):
        self.replies = []
        self.prompts = []
        self.schemas = []
        self.before_reply = None

    def ask(self, prompt, **options):
        self.prompts.append(prompt)
        self.schemas.append(options.get("schema"))
        if self.before_reply:
            self.before_reply()
        reply = self.replies.pop(0)
        return {
            "text": json.dumps(reply, ensure_ascii=False) if isinstance(reply, dict) else reply,
            "thread_id": options.get("thread_id") or f"relation-thread-{len(self.prompts)}",
        }


@pytest.fixture
def relation_session(tmp_path):
    model = RelationModel()
    app = create_app(tmp_path / "data", lambda _: model)
    client = TestClient(app, headers={"X-Learning-Map": "1"})
    course = client.post("/api/sample").json()
    client.post("/api/settings", json={"ai_enabled": True})
    return client, app.state.store, model, course


def node_path(course, index=0):
    return f"/api/courses/{course['id']}/nodes/{course['nodes'][index]['id']}"


def relation_spec(source, target, **overrides):
    return {
        "source": source,
        "target": target,
        "relation": "帮助理解",
        "explanation": "RELATION_EXPLANATION_SENTINEL",
        "when_to_use": "RELATION_USE_SENTINEL",
        "basis": "RELATION_BASIS_SENTINEL",
        "evidence_kind": "material_quote",
        "sources": [{"material_id": "sample-material", "page": 1, "quote": "A relation stores tuples"}],
        "uncertain": False,
        "forward_difficulty": "沿 source 到 target：简单",
        "reverse_difficulty": "反向迁移：较难",
        "presentation": "simple",
        **overrides,
    }


def draft_for(course, relations):
    material_id = course["materials"][0]["id"]
    nodes = []
    for index, node in enumerate(course["nodes"][:3]):
        page = index + 1
        quote = course["materials"][0]["pages"][page - 1]["text"].splitlines()[0]
        nodes.append({
            "key": f"node-{index}",
            "title": node["title"],
            "summary": node["summary"],
            "week": node["week"],
            "sources": [{"material_id": material_id, "page": page, "quote": quote}],
            "prerequisites": [],
            "uncertain": False,
        })
    fixed = []
    for item in relations:
        item = copy.deepcopy(item)
        for source in item["sources"]:
            if source["material_id"] == "sample-material":
                source["material_id"] = material_id
        fixed.append(item)
    return {"nodes": nodes, "relations": fixed}


def generate_relations(client, course, model, relations):
    model.replies.append(draft_for(course, relations))
    response = client.post(f"/api/courses/{course['id']}/generate")
    assert response.status_code == 200, response.text
    return response.json()


def relation_edges(course):
    return [edge for edge in course["edges"] if edge.get("explanation") == "RELATION_EXPLANATION_SENTINEL"]


def test_map_relations_preserve_existing_nodes_and_create_synthesis_only_when_selected(relation_session):
    client, store, model, course = relation_session
    client.post(node_path(course) + "/mark", json={"status": "studied"})
    before = store.course(course["id"])
    relation = relation_spec("node-0", "node-1")
    relation.update(synthesis_title="关系综合复习", synthesis_summary="结合两类关系解释数据库概念。")
    generated_synthesis = relation_spec(
        "node-1", "node-2", presentation="synthesis",
        synthesis_title="事务与提交综合", synthesis_summary="解释事务和提交如何共同保证变更。",
    )
    generated = generate_relations(client, course, model, [relation, generated_synthesis])

    original_ids = {node["id"] for node in before["nodes"]}
    assert original_ids.issubset({node["id"] for node in generated["nodes"]})
    first = next(node for node in generated["nodes"] if node["id"] == course["nodes"][0]["id"])
    assert first["status"] == "studied"
    edges = relation_edges(generated)
    edge = next(item for item in edges if item["source"] == course["nodes"][0]["id"])
    assert edge["confirmed"] is False
    assert edge["uncertain"] is False
    assert edge["forward_difficulty"] != edge["reverse_difficulty"]
    assert not edge.get("synthesis_node_id")
    generated_edge = next(item for item in edges if item["source"] == course["nodes"][1]["id"])
    assert generated_edge["presentation"] == "synthesis"
    generated_node = next(node for node in generated["nodes"] if node["id"] == generated_edge["synthesis_node_id"])
    assert generated_node["kind"] == "synthesis"
    assert set(generated_node["related_node_ids"]) == {generated_edge["source"], generated_edge["target"]}

    revision = generated["revision"]
    converted = client.post(
        f"/api/courses/{course['id']}/relations/{edge['id']}/presentation",
        json={"presentation": "synthesis", "revision": revision},
    )
    assert converted.status_code == 200, converted.text
    synthesis_course = converted.json()
    edge = next(item for item in relation_edges(synthesis_course) if item["id"] == edge["id"])
    synthesis = next(node for node in synthesis_course["nodes"] if node["id"] == edge["synthesis_node_id"])
    assert synthesis["kind"] == "synthesis"
    assert set(synthesis["related_node_ids"]) == {edge["source"], edge["target"]}
    assert synthesis["relation_id"] == edge["id"]
    assert synthesis["prerequisites"] == []
    assert synthesis["unlocked"]

    synthesis_url = f"/api/courses/{course['id']}/nodes/{synthesis['id']}"
    model.replies.append({"prompt": "解释综合概念", "kind": "组合", "rubric": "说明两个关系如何共同适用"})
    questioned = client.post(synthesis_url + "/question")
    assert questioned.status_code == 200, questioned.text
    model.replies.append({"outcome": "passed", "reasoning": "结合两概念解释正确", "blockers": [], "next_step": "继续"})
    assessed = client.post(synthesis_url + "/attempts", data={"answer": "两个关系共同用于分析数据"})
    assert assessed.status_code == 200, assessed.text
    learned_synthesis = next(node for node in assessed.json()["nodes"] if node["id"] == synthesis["id"])
    assert learned_synthesis["attempts"][-1]["judgment"]["outcome"] == "passed"
    assert learned_synthesis["status"] == "passed"

    simple = client.post(
        f"/api/courses/{course['id']}/relations/{edge['id']}/presentation",
        json={"presentation": "simple", "revision": assessed.json()["revision"]},
    )
    assert simple.status_code == 200, simple.text
    after_simple = simple.json()
    assert next(item for item in relation_edges(after_simple) if item["id"] == edge["id"])["presentation"] == "simple"
    assert synthesis["id"] in {node["id"] for node in after_simple["nodes"]}


def test_complex_synthesis_links_three_nodes_and_derived_edges_follow_canonical_edits(relation_session):
    client, _, model, course = relation_session
    relation = relation_spec(
        "node-0", "node-1", related_keys=["node-2"], presentation="synthesis",
        synthesis_title="三概念综合联系", synthesis_summary="结合关系、事务与提交解释数据变更。",
    )
    generated = generate_relations(client, course, model, [relation])
    edge = relation_edges(generated)[0]
    assert set(edge["related_node_ids"]) == {node["id"] for node in course["nodes"][:3]}
    synthesis_id = edge["synthesis_node_id"]
    synthesis = next(node for node in generated["nodes"] if node["id"] == synthesis_id)
    assert set(synthesis["related_node_ids"]) == set(edge["related_node_ids"])
    derived = [item for item in generated["edges"] if item.get("origin_relation_id") == edge["id"]]
    assert {item["source"] for item in derived} == set(edge["related_node_ids"])
    assert all(item["target"] == synthesis_id and item["controls_unlock"] is False for item in derived)

    edit = client.post(f"/api/courses/{course['id']}/relations/{derived[0]['id']}", json={
        "revision": generated["revision"],
        "relation": "归纳关系",
        "explanation": "CANONICAL_EDIT_SENTINEL",
        "when_to_use": "跨三个概念解释一个问题",
        "basis": "当前材料与用户复核",
        "forward_difficulty": "综合较难",
        "reverse_difficulty": "拆解较容易",
    })
    assert edit.status_code == 200, edit.text
    canonical = next(item for item in edit.json()["edges"] if item["id"] == edge["id"])
    projected_links = [item for item in edit.json()["edges"] if item.get("origin_relation_id") == edge["id"]]
    assert canonical["explanation"] == "CANONICAL_EDIT_SENTINEL"
    for item in projected_links:
        assert item["explanation"] == canonical["explanation"]
        assert item["when_to_use"] == canonical["when_to_use"]
        assert item["basis"] == canonical["basis"]
        assert item["forward_difficulty"] == canonical["forward_difficulty"]
        assert item["reverse_difficulty"] == canonical["reverse_difficulty"]
        assert item["confirmed"] is False
        assert item["relation"] == "综合联系"

    confirmed = client.post(
        f"/api/courses/{course['id']}/relations/{projected_links[0]['id']}/confirm",
        json={"revision": edit.json()["revision"]},
    )
    assert confirmed.status_code == 200, confirmed.text
    canonical = next(item for item in confirmed.json()["edges"] if item["id"] == edge["id"])
    projected_links = [item for item in confirmed.json()["edges"] if item.get("origin_relation_id") == edge["id"]]
    assert canonical["confirmed"] is True
    assert all(item["confirmed"] is True for item in projected_links)


def test_same_relation_explanation_with_distinct_basis_or_citations_is_not_deduplicated(relation_session):
    client, _, model, course = relation_session
    first = relation_spec("node-0", "node-1")
    second = relation_spec(
        "node-0", "node-1",
        basis="A separate source supports the comparison.",
        sources=[{
            "material_id": "sample-material", "page": 2,
            "quote": "A primary key uniquely identifies a row and cannot be null.",
        }],
    )
    generated = generate_relations(client, course, model, [first, second])
    relations = relation_edges(generated)
    assert len(relations) == 2
    assert len({edge["id"] for edge in relations}) == 2
    assert {edge["basis"] for edge in relations} == {first["basis"], second["basis"]}
    assert {edge["sources"][0]["page"] for edge in relations} == {1, 2}


@pytest.mark.parametrize("change", ["relation", "counterpart_status"])
def test_ai_result_is_rejected_when_a_relationship_or_related_node_changes_mid_request(relation_session, change):
    client, store, model, course = relation_session
    generated = generate_relations(client, course, model, [relation_spec("node-0", "node-1")])
    edge = relation_edges(generated)[0]

    def update_while_model_waits():
        if change == "relation":
            current = store.course(course["id"])
            response = client.post(f"/api/courses/{course['id']}/relations/{edge['id']}", json={
                "revision": current["revision"],
                "relation": "工具关系",
                "explanation": "UPDATED_DURING_AI_SENTINEL",
                "when_to_use": "模型请求等待期间更新",
                "basis": "并发修改",
                "forward_difficulty": "简单",
                "reverse_difficulty": "较难",
            })
        else:
            response = client.post(node_path(course, 1) + "/mark", json={"status": "studied"})
        assert response.status_code == 200, response.text

    model.before_reply = update_while_model_waits
    model.replies.append("此结果必须被丢弃")
    response = client.post(node_path(course) + "/chat", json={"message": "解释联系"})
    assert response.status_code == 409
    current = store.course(course["id"])
    assert current["nodes"][0]["chats"] == []
    if change == "relation":
        assert next(item for item in current["edges"] if item["id"] == edge["id"])["explanation"] == "UPDATED_DURING_AI_SENTINEL"


def test_structured_map_schema_requires_nested_defaults_but_old_payload_may_omit_relations(relation_session):
    client, _, model, course = relation_session
    payload = draft_for(course, [])
    legacy_payload = {key: value for key, value in payload.items() if key != "relations"}
    assert MapDraft.model_validate(legacy_payload).relations == []

    model.replies.append(legacy_payload)
    response = client.post(f"/api/courses/{course['id']}/generate")
    assert response.status_code == 200, response.text
    generated = response.json()
    schema = model.schemas[-1]
    assert isinstance(schema, dict)

    def check_required_fields(value):
        if isinstance(value, dict):
            properties = value.get("properties")
            if value.get("type") == "object" and isinstance(properties, dict):
                assert set(value.get("required", [])) == set(properties)
            for nested in value.values():
                check_required_fields(nested)
        elif isinstance(value, list):
            for nested in value:
                check_required_fields(nested)

    check_required_fields(schema)
    assert "relations" not in legacy_payload
    assert len(generated["nodes"]) >= len(course["nodes"])


def test_same_title_new_meaning_is_saved_as_scoped_variant_without_replacing_node_progress(relation_session):
    client, store, model, course = relation_session
    second_pdf = io.BytesIO()
    canvas = Canvas(second_pdf)
    canvas.drawString(40, 700, "VARIANT_EXCLUDED_PAGE_SENTINEL")
    canvas.save()
    uploaded = client.post(
        f"/api/courses/{course['id']}/materials",
        files={"files": ("variant.pdf", second_pdf.getvalue(), "application/pdf")},
    )
    assert uploaded.status_code == 200, uploaded.text
    second_material_id = uploaded.json()["materials"][1]["id"]
    marked = client.post(node_path(course) + "/mark", json={"status": "studied"})
    assert marked.status_code == 200, marked.text
    before = store.course(course["id"])
    original = before["nodes"][0]

    draft = draft_for(course, [])
    draft["nodes"][0]["summary"] = "VARIANT_SUMMARY_SENTINEL"
    draft["nodes"][0]["sources"] = [{
        "material_id": second_material_id,
        "page": 1,
        "quote": "VARIANT_EXCLUDED_PAGE_SENTINEL",
    }]
    model.replies.append(draft)
    generated_response = client.post(f"/api/courses/{course['id']}/generate")
    assert generated_response.status_code == 200, generated_response.text
    generated = generated_response.json()
    node = next(item for item in generated["nodes"] if item["id"] == original["id"])
    assert node["summary"] == original["summary"]
    assert node["status"] == "studied"
    assert node["material_variants"] == [{
        "summary": "VARIANT_SUMMARY_SENTINEL",
        "sources": [{
            "material_id": second_material_id,
            "page": 1,
            "quote": "VARIANT_EXCLUDED_PAGE_SENTINEL",
        }],
        "uncertain": True,
    }]

    model.replies.append("课程范围可以看到不同材料的意义变体")
    assert client.post(node_path(course) + "/chat", json={"message": "解释本节点"}).status_code == 200
    assert "VARIANT_SUMMARY_SENTINEL" in model.prompts[-1]
    selected = client.post(f"/api/courses/{course['id']}/review-scope", json={
        "enabled": True,
        "material_ids": [generated["materials"][0]["id"]],
        "ai_scope": "selected",
    })
    assert selected.status_code == 200, selected.text
    model.replies.append("当前单一PDF没有包含另一材料中的变体")
    assert client.post(node_path(course) + "/chat", json={"message": "严格复习本节点"}).status_code == 200
    assert "VARIANT_SUMMARY_SENTINEL" not in model.prompts[-1]
    assert "VARIANT_EXCLUDED_PAGE_SENTINEL" not in model.prompts[-1]


def test_relation_endpoints_collapsing_to_same_title_roll_back_map_generation(relation_session):
    client, store, model, course = relation_session
    before = store.course(course["id"])
    draft = draft_for(course, [relation_spec("node-0", "node-1")])
    draft["nodes"][1]["title"] = draft["nodes"][0]["title"]
    model.replies.append(draft)
    response = client.post(f"/api/courses/{course['id']}/generate")
    assert response.status_code == 400
    assert "知识联系的端点合并为同一知识节点" in response.json()["detail"]
    after = store.course(course["id"])
    assert after["nodes"] == before["nodes"]
    assert after["edges"] == before["edges"]
    assert after["revision"] == before["revision"]


def test_map_generation_keeps_user_relation_edit_made_while_model_is_waiting(relation_session):
    client, store, model, course = relation_session
    initial = generate_relations(client, course, model, [relation_spec("node-0", "node-1")])
    canonical = relation_edges(initial)[0]
    original_node_ids = {node["id"] for node in initial["nodes"]}
    stale_draft = draft_for(initial, [
        relation_spec("node-0", "node-1", explanation="STALE_MAP_RELATION_SENTINEL"),
    ])

    def edit_existing_relation_while_model_waits():
        with store.edit(course["id"]) as (current, _):
            current_edge = next(item for item in current["edges"] if item["id"] == canonical["id"])
            current_edge["explanation"] = "USER_EDIT_DURING_GENERATION_SENTINEL"

    model.before_reply = edit_existing_relation_while_model_waits
    model.replies.append(stale_draft)
    response = client.post(f"/api/courses/{course['id']}/generate")
    assert response.status_code == 409

    after = store.course(course["id"])
    assert {node["id"] for node in after["nodes"]} == original_node_ids
    assert len(after["edges"]) == len(initial["edges"])
    preserved = next(item for item in after["edges"] if item["id"] == canonical["id"])
    assert preserved["explanation"] == "USER_EDIT_DURING_GENERATION_SENTINEL"
    assert all(item.get("explanation") != "STALE_MAP_RELATION_SENTINEL" for item in after["edges"])


def test_unconfirmed_relation_can_be_edited_confirmed_and_rejects_stale_revision(relation_session):
    client, store, model, course = relation_session
    generated = generate_relations(client, course, model, [relation_spec("node-0", "node-1", uncertain=True)])
    edge = relation_edges(generated)[0]
    base = f"/api/courses/{course['id']}/relations/{edge['id']}"
    revision = generated["revision"]

    edited = client.post(base, json={
        "revision": revision,
        "relation": "相似或对比",
        "explanation": "用户确认的解释",
        "when_to_use": "在比较两种键时",
        "basis": "核对了示例材料",
        "forward_difficulty": "正向容易",
        "reverse_difficulty": "反向需要迁移",
    })
    assert edited.status_code == 200, edited.text
    edge = next(item for item in edited.json()["edges"] if item["id"] == edge["id"])
    assert edge["confirmed"] is False
    assert edge["uncertain"] is True
    assert edge["relation"] == "相似或对比"
    assert edge["forward_difficulty"] != edge["reverse_difficulty"]

    stale = client.post(f"{base}/confirm", json={"revision": revision})
    assert stale.status_code == 409
    current = store.course(course["id"])
    confirmed = client.post(f"{base}/confirm", json={"revision": current["revision"]})
    assert confirmed.status_code == 200, confirmed.text
    edge = next(item for item in confirmed.json()["edges"] if item["id"] == edge["id"])
    assert edge["confirmed"] is True
    assert edge["uncertain"] is True


def test_strict_pdf_context_omits_cross_material_relation_and_its_counterpart(relation_session):
    client, store, model, course = relation_session
    output = io.BytesIO()
    pdf = Canvas(output)
    pdf.drawString(40, 700, "SECOND_SOURCE_RELATION_SENTINEL")
    pdf.save()
    uploaded = client.post(
        f"/api/courses/{course['id']}/materials",
        files={"files": ("second.pdf", output.getvalue(), "application/pdf")},
    )
    assert uploaded.status_code == 200, uploaded.text
    second_material_id = uploaded.json()["materials"][1]["id"]
    with store.edit(course["id"]) as (current, _):
        # The relationship semantics draw on both PDFs. A strict single-PDF session must not
        # reveal any part of this relation, even though one endpoint is in the selected PDF.
        first_id, second_id = current["nodes"][:2]
        current["edges"].append({
            "id": "cross-source-relation",
            "source": first_id["id"],
            "target": second_id["id"],
            "relation": "帮助理解",
            "explanation": "CROSS_RELATION_SEMANTICS_SENTINEL",
            "when_to_use": "CROSS_RELATION_USE_SENTINEL",
            "basis": "CROSS_RELATION_BASIS_SENTINEL",
            "evidence_kind": "material_inference",
            "sources": [
                {"material_id": current["materials"][0]["id"], "page": 1, "quote": "A relation stores tuples"},
                {"material_id": second_material_id, "page": 1, "quote": "SECOND_SOURCE_RELATION_SENTINEL"},
            ],
            "forward_difficulty": "forward",
            "reverse_difficulty": "reverse",
            "uncertain": False,
            "confirmed": True,
            "presentation": "simple",
        })
    fresh_course = store.course(course["id"])
    response = client.post(f"/api/courses/{course['id']}/review-scope", json={
        "enabled": True,
        "material_ids": [fresh_course["materials"][0]["id"]],
        "ai_scope": "selected",
    })
    assert response.status_code == 200, response.text
    model.replies.append("所选 PDF 范围内的回答")
    chat = client.post(node_path(course) + "/chat", json={"message": "解释当前节点"})
    assert chat.status_code == 200, chat.text
    prompt = model.prompts[-1]
    assert "CROSS_RELATION_SEMANTICS_SENTINEL" not in prompt
    assert "CROSS_RELATION_USE_SENTINEL" not in prompt
    assert "CROSS_RELATION_BASIS_SENTINEL" not in prompt
    assert "SECOND_SOURCE_RELATION_SENTINEL" not in prompt


def test_chat_question_grading_and_lesson_receive_relationship_and_learning_state(relation_session):
    client, _, model, course = relation_session
    generate_relations(client, course, model, [relation_spec("node-0", "node-1")])
    path = node_path(course)
    marked = client.post(path + "/mark", json={"status": "studied"})
    assert marked.status_code == 200, marked.text

    model.replies.append("结合当前关系说明的回答")
    assert client.post(path + "/chat", json={"message": "关系如何帮助学习？"}).status_code == 200
    assert "RELATION_EXPLANATION_SENTINEL" in model.prompts[-1]
    assert "studied" in model.prompts[-1]

    model.replies.append({"prompt": "比较两个概念", "kind": "组合", "rubric": "正确说明概念关系"})
    assert client.post(path + "/question").status_code == 200
    assert "RELATION_EXPLANATION_SENTINEL" in model.prompts[-1]

    model.replies.append({"outcome": "uncertain", "reasoning": "需要更多解释", "blockers": ["需举例"], "next_step": "补充例子"})
    assert client.post(path + "/attempts", data={"answer": "我认为两个概念有关"}).status_code == 200
    assert "RELATION_EXPLANATION_SENTINEL" in model.prompts[-1]

    model.replies.append({
        "title": "关系复习小课",
        "goal": "用关系线索理解概念",
        "html": "<h2>例子</h2><p>比较两种概念，再根据资料中的证据解释它们如何联系，以及在面对具体数据库问题时分别何时使用。</p><p>尝试把关系线索用于一个新的情境，并说明你的判断依据。</p>",
        "check_question": "如何用关系解释概念？",
        "check_answer": "结合两个端点说明。",
        "recap": "关系提供理解线索。",
    })
    lesson = client.post(path + "/lessons", json={"request_id": "relation-lesson-0001", "kind": "initial"})
    assert lesson.status_code == 200, lesson.text
    assert "RELATION_EXPLANATION_SENTINEL" in model.prompts[-1]
    assert "studied" in model.prompts[-1]


def test_strict_synthesis_context_does_not_send_course_wide_endpoint_summaries(relation_session):
    client, store, model, course = relation_session
    with store.edit(course["id"]) as (current, _):
        current["nodes"][0]["summary"] = "COURSE_WIDE_ENDPOINT_SUMMARY_ONE_SENTINEL"
        current["nodes"][1]["summary"] = "COURSE_WIDE_ENDPOINT_SUMMARY_TWO_SENTINEL"
    current_course = store.course(course["id"])
    relation = relation_spec(
        "node-0", "node-1", presentation="synthesis",
        synthesis_title="综合节点范围复习", synthesis_summary="仅依据被选资料复习。",
    )
    generated = generate_relations(client, current_course, model, [relation])
    edge = relation_edges(generated)[0]
    synthesis = next(node for node in generated["nodes"] if node["id"] == edge["synthesis_node_id"])
    selected_id = generated["materials"][0]["id"]
    selected = client.post(f"/api/courses/{course['id']}/review-scope", json={
        "enabled": True,
        "material_ids": [selected_id],
        "ai_scope": "selected",
    })
    assert selected.status_code == 200, selected.text
    model.replies.append("仅根据当前资料的综合说明")
    response = client.post(
        f"/api/courses/{course['id']}/nodes/{synthesis['id']}/chat",
        json={"message": "复习综合知识点"},
    )
    assert response.status_code == 200, response.text
    prompt = model.prompts[-1]
    assert "COURSE_WIDE_ENDPOINT_SUMMARY_ONE_SENTINEL" not in prompt
    assert "COURSE_WIDE_ENDPOINT_SUMMARY_TWO_SENTINEL" not in prompt


def test_legacy_edges_receive_safe_projection_defaults_without_rewriting_storage(relation_session):
    client, store, _, course = relation_session
    before = store.course(course["id"])
    legacy = copy.deepcopy(before["edges"][0])
    view = client.get(f"/api/courses/{course['id']}").json()
    projected = next(edge for edge in view["edges"] if edge["id"] == legacy["id"])
    assert projected["confirmed"] is False
    assert projected["uncertain"] is legacy["uncertain"]
    assert projected["presentation"] == "simple"
    assert projected["evidence_kind"] == "ai_inference"
    assert "forward_difficulty" in projected and "reverse_difficulty" in projected
    assert store.course(course["id"])["edges"][0] == legacy


def test_unverified_material_quote_is_kept_uncertain_and_snapshot_restore_preserves_relation(relation_session):
    client, store, model, course = relation_session
    relation = relation_spec(
        "node-0", "node-1",
        sources=[{"material_id": "sample-material", "page": 1, "quote": "CLAIMED_BUT_ABSENT_QUOTE"}],
    )
    generated = generate_relations(client, course, model, [relation])
    edge = relation_edges(generated)[0]
    assert edge["uncertain"] is True
    assert edge["confirmed"] is False
    assert edge["sources"][0]["quote"] == ""

    snapshot = client.post(f"/api/courses/{course['id']}/snapshot")
    assert snapshot.status_code == 200, snapshot.text
    versions = client.get(f"/api/courses/{course['id']}/versions").json()
    version_id = versions[0]["id"]
    current = store.course(course["id"])
    confirmed = client.post(
        f"/api/courses/{course['id']}/relations/{edge['id']}/confirm",
        json={"revision": current["revision"]},
    )
    assert confirmed.status_code == 200, confirmed.text
    preview = client.post(
        f"/api/courses/{course['id']}/restore-preview", json={"version_id": version_id}
    )
    assert preview.status_code == 200, preview.text
    restored = client.post(
        f"/api/courses/{course['id']}/restore", json={"token": preview.json()["token"]}
    )
    assert restored.status_code == 200, restored.text
    restored_edge = next(item for item in relation_edges(restored.json()) if item["id"] == edge["id"])
    assert restored_edge["confirmed"] is False
    assert restored_edge["uncertain"] is True
    assert restored_edge["sources"][0]["quote"] == ""
